user_prompt:
method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0  // The input list must not be empty.
    ensures |result| == |xs| - 1  // The length of the result is one less than the input.
    ensures forall i :: 0 <= i < |result| ==> result[i] == (i + 1) * xs[i + 1]  // Each coefficient in the result is correctly computed.
{
    var n := |xs|; 
    var res := new int[n - 1]; 
    var i := 0;
    while i < n - 1
        invariant 0 <= i <= n - 1  // i is within bounds.
        invariant |res| == i  // The length of res is i.
    {
        res[i] := (i + 1) * xs[i + 1];
        i := i + 1;
    }
    result := res;  
}
